UPDATE `assets_pera` SET `pera_metadata_json` = json_set(`pera_metadata_json`, '$.isUnique', json(CASE WHEN EXISTS (SELECT 1 FROM `assets_node` n WHERE n.`asset_id` = `assets_pera`.`asset_id` AND n.`scope` = `assets_pera`.`scope` AND n.`total_supply` = '1' AND n.`decimals` = 0) THEN 'true' ELSE 'false' END)) WHERE `asset_type` = 'collectible' AND json_valid(`pera_metadata_json`) AND `scope` LIKE 'algorand/%';
